function difficulty(){return mode==='endless'?Math.min(12,Math.floor(z/180)):Math.floor(level/3)*.7+(level%3)*.35}
function generateBlock(start,d){let safe=Math.floor(Math.random()*3)+1,type=Math.floor(Math.random()*4),width=d>=4?1:2;for(let j=0;j<30;j++){let r=start+j,t=[1,1,1,1,1];if(start>0&&j>=9&&j<=18){if(type===0&&j>=12&&j<=13)t=[0,0,0,0,0];if(type===1)t=t.map((v,l)=>l===safe||(l===safe-1&&width===2)?1:(l+safe)%2?2:0);if(type===2&&j>=12&&j<16){t[(safe+2)%5]=2;if(d>1)t[(safe+3)%5]=2}if(type===3&&j>=11&&j<=16)t=t.map((v,l)=>l===safe||l===safe-1?1:0)}if(r>=nextFuelRow&&j===24){t[safe]=3;nextFuelRow=r+fuelSpacing(r)}rows[r]=t;if(r>5&&j%12===6&&Math.random()<.6){let candidates=t.map((v,l)=>v===1?l:-1).filter(l=>l>=0);if(candidates.length)coins.set(r,{lane:candidates[Math.floor(Math.random()*candidates.length)],height:.4})}}generated=start+30}
