const hazardRoof=hazardTunnelRoofAt(activeRoadData(),Math.floor(z),x);if(hazardRoof&&((tunnelGrounded&&Math.abs(y-hazardRoof)<.06)||(vy<=0&&(previousY>=hazardRoof-.03||diagonalTunnelLanding(tunnelPreviousX,previousY,x,z,y))&&y<=hazardRoof+.02))){y=hazardRoof;finish(false,'위험 터널 지붕 접촉');return;}
